from .units import WeightError, kg_to_g, normalize_kg

MAX_TOTAL_KG = "2147483.647"  # the carrier system stores grams in a signed 32-bit column


def check_total_kg(weight_kg):
    """Return the canonical total; a total above the carrier limit raises WeightError.

    >>> check_total_kg("2147483.647")
    '2147483.647'
    """
    weight = normalize_kg(weight_kg)
    if kg_to_g(weight) > kg_to_g(MAX_TOTAL_KG):
        raise WeightError("total weight exceeds the carrier limit")
    return weight
EOF
