"""Validation of raw order lines. The limits come from the table in the Item docstring."""
import re

from .models import Item
from .units import WeightError, kg_to_g

_LINE = re.compile(r"^\s+(\w+): (str|int|kg), ([0-9]+(?:\.[0-9]+)?)\.\.([0-9]+(?:\.[0-9]+)?)\s*$")


def _parse(doc):
    rules = {}
    for line in doc.splitlines():
        match = _LINE.match(line)
        if match:
            name, kind, low, high = match.groups()
            rules[name] = (kind, low, high)
    return rules


RULES = _parse(Item.__doc__)


def _bound(kind, text):
    return kg_to_g(text) if kind == "kg" else int(text)


def validate_item(data):
    """Return a list of problems, each 'field: reason'. Empty means valid."""
    problems = []
    for name, (kind, low_text, high_text) in RULES.items():
        if name not in data:
            problems.append(f"{name}: missing")
            continue
        value = data[name]
        low, high = _bound(kind, low_text), _bound(kind, high_text)
        if kind == "str":
            if not isinstance(value, str):
                problems.append(f"{name}: not a string")
            elif not low <= len(value) <= high:
                problems.append(f"{name}: length out of range {low_text}..{high_text}")
        elif kind == "kg":
            try:
                grams = kg_to_g(value)
            except WeightError as exc:
                problems.append(f"{name}: {exc}")
                continue
            if not low <= grams <= high:
                problems.append(f"{name}: out of range {low_text}..{high_text}")
        elif isinstance(value, bool) or not isinstance(value, int):
            problems.append(f"{name}: not an integer")
        elif not low <= value <= high:
            problems.append(f"{name}: out of range {low_text}..{high_text}")
    return problems
